function LadderStruggleRecordPopup:InitComponent()
    UIEventProxy.Create(self.RT_BgClick.gameObject).onPointerClick = function()
        UIModule.BackDialog()
    end
    self.playerTeamLTArray = {}
    local count = self.RT_TeamGroup.transform.childCount
    for i = 1, count, 1 do
        local playerTeamRT = self.RT_TeamGroup:GetChild(i-1)
        if not IsNull(playerTeamRT) then
            local LB_playerTeam = GetLuaBehaviour(playerTeamRT.gameObject, PlayerTeamLuaPath)
            table.insert(self.playerTeamLTArray, LB_playerTeam.Env)

            LB_playerTeam.Env:SetSystem(self.systemName)
        end
    end
end

--- 初始化队伍组件
function LadderStruggleRecordPopup:InitTeamGroup()
    if isNull(self.playerTeam) or isNull(self.enemyTeam) then
        return
    end
    local data = self.processedData
    for i, waveData in ipairs(data) do
        local LT_playerTeam = self.playerTeamLTArray[i]
        if LT_playerTeam then
            -- LT_playerTeam:InitPanelInfo(waveData.initData.playerTeam, waveData.initData.enemyTeam)
            LT_playerTeam:InitTeamInfo(self.playerTeam[i].cardsInfo, self.enemyTeam[i].cardsInfo)
        else
            print("[回看]",i,"队伍组件为空")
        end
    end
end

