--- 设置播放录像需要的数据
function LadderStruggleRecordPopup:SetBattleRecord()
    local struggleData = self.sourceData
    for i, waveData in ipairs(struggleData) do
        local LT_playerTeam = self.playerTeamLTArray[i]
        if LT_playerTeam then
            LT_playerTeam:SetBattleRecord(waveData)
            LT_playerTeam:SetBattleSessionIndex(i)
        else
            print("[回看]",i,"队伍组件为空")
        end
    end
end

--- 设置对战结果
function LadderStruggleRecordPopup:SetTeamBattleResult()
    local myId = checkNumber(GameUtils.GetPlayerId())

    local struggleData = self.processedData
    for i, waveData in ipairs(struggleData) do
        if i > self.totalSessionCount then
            self:SetTeamBattleState(i, 3)
        else
            -- 作为防守方时，initData中的selfId是对方的id，战报中的aliveData和winState要翻转
            local isMyL = checkNumber(waveData.initData.selfId) == myId
            if not isNull(waveData.aliveData) then
                if isMyL then
                    self:SetTeamAliveState(i, waveData.aliveData.L, waveData.aliveData.R)
                else
                    self:SetTeamAliveState(i, waveData.aliveData.R, waveData.aliveData.L)
                end
            end
            local winState = waveData.win == true and 1 or 2
            if isMyL then
                self:SetTeamBattleState(i, winState)
            else
                self:SetTeamBattleState(i, 3 - winState)
            end
        end
    end
end

function LadderStruggleRecordPopup:SetPlayerNameUI()
    self.Txt_PlayerNameL.text = self.playerNameL
    self.Txt_PlayerNameR.text = self.playerNameR
end

--- 请求对战记录
---@param id any
function LadderStruggleRecordPopup:RequestBattleRecord(id)
    local succeed = false
    local operation = GameUtils.Request(self.component.InterfaceVideo, {videoId = id}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        succeed = true
        local jsonData = response.data
        self.sourceData = table.deserialize(jsonData.battleData)
        
        LadderStruggleMgr = import('Game.UI.UIBattling.LadderStruggle.LadderStruggleMgr')
        LadderStruggleMgr:Init()
        LadderStruggleMgr:SetLadderStruggleData(self.sourceData, nil)
        LadderStruggleMgr:Preprocessing()
        self.processedData = LadderStruggleMgr.struggleData
        self.totalSessionCount = LadderStruggleMgr.totalSessionCount
        -- local LadderStruggleMgr = import('Game.UI.UIBattling.LadderStruggle.LadderStruggleMgr')
        -- self.processedData, _, _, self.totalSessionCount = LadderStruggleMgr:PreprocessingData(self.sourceData)
        -- LadderStruggleMgr = nil
        self:GetPlayerName(self.processedData[1].initData)
    end)

    while not succeed do
        cs_coroutine.yield_return()
    end
end

function LadderStruggleRecordPopup:GetPlayerName(initData)
    local myId = checkNumber(GameUtils.GetPlayerId())
    for k, v in pairs(initData.campDesc) do
        if checkNumber(v.playerId) == myId then
            self.playerNameL = v.name
        else
            self.playerNameR = v.name
        end
    end
end

function LadderStruggleRecordPopup:CheckTeam(team)
    if isNull(team) then
        return
    end
    if isNull(team.team) then
        return
    end

    local originTeam = checkTable(team.team)

    local newTeam = {}
    for k, v in pairs(originTeam) do
        newTeam[checkNumber(k)] = v
    end

    return newTeam
end

return LadderStruggleRecordPopup